def FT(w):
    """(#R, #G, #B, longest block, number of blocks, length, palindrome, #colours, blocks all equal)"""
    G = [len(list(g)) for _, g in itertools.groupby(w)]
    return (w.count("R"), w.count("G"), w.count("B"), max(G), len(G), len(w),
            int(w == w[::-1]), len(set(w)), int(len(set(G)) == 1))

def UNIV():
    """The universe U: 8 kid-sentence templates, 38 concrete rules."""
    U =  [(0, i, n) for i in (0, 1, 2) for n in (2, 3, 4, 5)]   # exactly n red / green / blue beads
    U += [(0, 3, n) for n in (2, 3, 4, 5)]                      # the longest block is n beads long
    U += [(0, 4, n) for n in (3, 4, 5, 6, 7)]                   # there are exactly n blocks
    U += [(0, 5, n) for n in (6, 7, 8, 9, 10)]                  # the string is n beads long (competitor)
    U += [(0, 6, 1), (0, 7, 2), (0, 8, 1)]                      # palindrome / only 2 colours / equal blocks
    U += [(1, 0, 1), (1, 0, 2), (1, 2, 1)]                      # as many X beads as Y beads
    U += [(2, i, j) for i in (0, 1, 2) for j in (0, 1, 2) if i != j]  # all the X beads before all the Y
    return U

# The 23 rules that may be the HIDDEN one: probability <= 0.20 for a random string of a random
# length. The other 15 stay in U as COMPETITORS the generator must kill: the loose counts (2, 3),
# the loose longest-block values (2, 3), the loose block counts (5, 6) and every length rule.
ELIG = ((0,0,4),(0,0,5),(0,1,4),(0,1,5),(0,2,4),(0,2,5),(0,3,4),(0,3,5),(0,4,3),(0,4,4),(0,4,7),
