        (2,0,1),(2,0,2),(2,1,0),(2,1,2),(2,2,0),(2,2,1))

def TKEY(r):
    if r[0] == 0:
        return "count" if r[1] < 3 else {3: "maxrun", 4: "blocks", 5: "length",
                                         6: "palin", 7: "twocol", 8: "eqblk"}[r[1]]
    return "equal" if r[0] == 1 else "before"

U = UNIV()
BIT = {}
for k, r in enumerate(U):
    BIT[r] = 1 << k
D = {}
for r in U:
    if r[0] == 0:
        D[(r[1], r[2])] = BIT[r]
T1 = [r for r in U if r[0] == 1]
T2 = [r for r in U if r[0] == 2]

def MASK(w):
    f = FT(w)
    m = 0
    for i in range(9):
        m |= D.get((i, f[i]), 0)
    for r in T1:
        if f[r[1]] == f[r[2]]:
            m |= BIT[r]
    for r in T2:
        x = COL[r[1]]
        y = COL[r[2]]
        if x in w and y in w and w.rfind(x) < w.find(y):
            m |= BIT[r]
    return m

