    SATL[_r] = _d
TEMPL = {}
for _r in ELIG:
    TEMPL.setdefault(TKEY(_r), []).append(_r)
TKEYS = sorted(TEMPL)

def generate(seed):
    r = random.Random(seed)
    for _ in range(300):
        # template first, then a parameter, so no template is rare merely for having fewer rules
        rule = r.choice(TEMPL[r.choice(TKEYS)])
        d = SATL[rule]
        LS = [L for L in d if len(d[L]) > 2]          # lengths with room to spare
        b = BIT[rule]
        best = None
        for size in ((3, 2) if r.random() < 0.7 else (2, 3)):
            if len(LS) < size:
                continue
            for _t in range(120):
                # one example per length, all lengths different: the clue itself shows that the
                # length is never the rule, and the answer must use a length that is not there
                T = [r.choice(d[L]) for L in r.sample(LS, size)]
                m = -1
                for i in T:
                    m &= MSK[i]
                if m != b:                            # the set must leave exactly this rule alive
                    continue
                ok = True
                for k in range(size):                 # ... and no proper subset may
                    mm = -1
                    for i in T[:k] + T[k + 1:]:
                        mm &= MSK[i]
                    if mm.bit_count() == 1:
                        ok = False
                        break
                if ok:
                    best = T
                    break
            if best:
                break
        if best is None:
            continue
        # the answer must be buildable at some unused length
        free = sum(len(d.get(L, ())) for L in range(6, 11) if L not in [len(POOL[i]) for i in best])
        if free < 3:
            continue
        return "\n".join(POOL[i] for i in best)
    return "RRGGBB\nBGRBGRB"

